(() => {
  'use strict';
  const PET_FALLBACKS = {"pet-barney.webp": "data:image/webp;base64,", "pet-murka.webp": "data:image/webp;base64,", "pet-lucky.webp": "data:image/webp;base64,"};
  const normalizeImage = (img) => {
    if (!(img instanceof HTMLImageElement)) return;
    const raw = img.getAttribute('src') || '';
    if (raw.startsWith('assets/')) {
      try { img.src = new URL(raw, document.baseURI).href; } catch (_) { /* keep original */ }
    }
    if (/pet-(barney|murka|lucky)\.webp(?:$|[?#])/i.test(img.src)) {
      img.decoding = 'async';
      img.loading = 'eager';
    }
  };
  const fallbackPet = (img) => {
    if (!(img instanceof HTMLImageElement) || img.dataset.petFallbackApplied === 'true') return;
    const src = img.getAttribute('src') || img.src || '';
    const match = src.match(/(pet-(?:barney|murka|lucky)\.webp)(?:$|[?#])/i);
    if (!match) return;
    const fallback = PET_FALLBACKS[match[1].toLowerCase()];
    if (!fallback) return;
    img.dataset.petFallbackApplied = 'true';
    img.src = fallback;
  };
  const scan = (root = document) => root.querySelectorAll?.('img').forEach(normalizeImage);
  document.addEventListener('error', (event) => fallbackPet(event.target), true);
  const observer = new MutationObserver((records) => {
    for (const record of records) for (const node of record.addedNodes) {
      if (!(node instanceof Element)) continue;
      if (node.matches('img')) normalizeImage(node);
      scan(node);
    }
  });
  const init = () => {
    scan();
    observer.observe(document.body, { childList:true, subtree:true });
    document.body.classList.add('clinic-polish-ready');
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once:true }); else init();
})();
